# Surah An-Nisa (chapter 4) — part 18 (final): ayat 171-176 (IDs 664-669)
SURAH = 4

ENTRIES = {
664: (
"اے اہلِ کتاب! اپنے دین میں غلو (حد سے تجاوز) نہ کرو — اور اللہ کے بارے میں صرف حق کہو — بے شک مسیح عیسیٰ ابنِ مریم — اللہ کے رسول ہیں اور اس کا ایک کلمہ (ہیں) — جو اس نے مریم کی طرف ڈالا — اور اس کی طرف سے روح (ہیں) — پس اللہ اور اس کے رسولوں پر ایمان لاؤ — اور یہ مت کہو کہ تین (معبود) ہیں — باز آ جاؤ — (یہ) تمہارے لیے بہتر ہے — بے شک اللہ ہی ایک معبود ہے — پاک ہے وہ اس سے کہ اس کے لیے کوئی بیٹا ہو — اس کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور اللہ کارساز ہونے کو کافی ہے",
"""۱۔ نصاریٰ کی غلطی — عیسیٰ علیہ السلام کو خدا کا بیٹا کہنا — قرآن کا واضح رد۔
۲۔ ’’يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللّٰہِ إِلَّا الْحَقَّ‘‘ — اے اہلِ کتاب! اپنے دین میں غلو (حد سے تجاوز) نہ کرو — اور اللہ کے بارے میں صرف حق کہو۔
۳۔ ’’إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللّٰہِ وَكَلِمَتُهُ أَلْقَاهَا إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ‘‘ — بے شک مسیح عیسیٰ ابنِ مریم — اللہ کے رسول ہیں اور اس کا ایک کلمہ (ہیں) — جو اس نے مریم کی طرف ڈالا — اور اس کی طرف سے روح (ہیں) — یعنی عیسیٰ علیہ السلام اللہ کے رسول ہیں — اللہ کا کلمہ اور اس کی روح — خدا نہیں۔
۴۔ ’’فَآمِنُوا بِاللّٰہِ وَرُسُلِهِ وَلَا تَقُولُوا ثَلَاثَۃٌ انتَهُوا خَيْرًا لَّكُمْ‘‘ — پس اللہ اور اس کے رسولوں پر ایمان لاؤ — اور یہ مت کہو کہ تین (معبود) ہیں — باز آ جاؤ — (یہ) تمہارے لیے بہتر ہے — یعنی تثلیث کا عقیدہ باطل ہے۔
۵۔ ’’إِنَّمَا اللّٰہُ إِلَٰهٌ وَاحِدٌ سُبْحَانَهُ أَن يَكُونَ لَهُ وَلَدٌ‘‘ — بے شک اللہ ہی ایک معبود ہے — پاک ہے وہ اس سے کہ اس کے لیے کوئی بیٹا ہو — یعنی اللہ واحد ہے — بیٹا رکھنا اس سے بہت دور ہے۔
۶۔ ’’لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَىٰ بِاللّٰہِ وَكِيلًا‘‘ — اس کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے — اور اللہ کارساز ہونے کو کافی ہے — یعنی ساری کائنات اللہ کی ہے۔
۷۔ عملی سبق: توحیدِ خالص پر ڈٹے رہو؛ اللہ کے بارے میں غلو اور جھوٹ سے بچو۔"""
),
665: (
"مسیحؑ — اللہ کا بندہ ہونے سے انکار نہیں کریں گے — اور نہ مقرب فرشتے — اور جو کوئی اللہ کی عبادت سے انکار کرے اور تکبر کرے — وہ (اللہ) ان سب کو اپنے پاس جمع کرے گا",
"""۱۔ عیسیٰؑ اور فرشتے دونوں اللہ کے بندے ہیں — کبھی انکار نہیں کریں گے۔
۲۔ ’’لَّن يَسْتَنكِفَ الْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلّٰہِ وَلَا الْمَلَائِكَۃُ الْمُقَرَّبُونَ‘‘ — مسیحؑ — اللہ کا بندہ ہونے سے انکار نہیں کریں گے — اور نہ مقرب فرشتے — یعنی عیسیٰؑ اور فرشتے دونوں اللہ کی عبادت پر فخر کرتے ہیں۔
۳۔ ’’وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا‘‘ — اور جو کوئی اللہ کی عبادت سے انکار کرے اور تکبر کرے — وہ (اللہ) ان سب کو اپنے پاس جمع کرے گا — یعنی عبادت سے انکار کرنے والوں کا حساب اللہ لے گا۔
۴۔ عملی سبق: تکبر اور عبادت سے انکار سے بچو؛ اللہ کے سامنے عاجز بندہ بنو۔"""
),
666: (
"پھر جو لوگ ایمان لائے اور نیک اعمال کیے — وہ انہیں ان کا پورا اجر دے گا اور انہیں اپنے فضل سے مزید دے گا — اور جو لوگ انکار کیا اور تکبر کیا — وہ انہیں دردناک عذاب دے گا — اور وہ اللہ کے سوا نہ کوئی کارساز پائیں گے اور نہ مددگار",
"""۱۔ ایمان والوں کا انعام — پورا اجر اور اللہ کا فضل۔
۲۔ ’’فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِ‘‘ — پھر جو لوگ ایمان لائے اور نیک اعمال کیے — وہ انہیں ان کا پورا اجر دے گا اور انہیں اپنے فضل سے مزید دے گا — یعنی اجر سے زیادہ بڑھ کر دے گا۔
۳۔ ’’وَأَمَّا الَّذِينَ اسْتَنكَفُوا وَاسْتَكْبَرُوا فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا‘‘ — اور جو لوگ انکار کیا اور تکبر کیا — وہ انہیں دردناک عذاب دے گا۔
۴۔ ’’وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللّٰہِ وَلِيًّا وَلَا نَصِيرًا‘‘ — اور وہ اللہ کے سوا نہ کوئی کارساز پائیں گے اور نہ مددگار۔
۵۔ عملی سبق: ایمان اور نیک عمل اختیار کرو؛ اللہ کا فضل حاصل کرو — تکبر سے بچو۔"""
),
667: (
"اے لوگو! تمہارے پاس تمہارے رب کی طرف سے ایک واضح دلیل آ چکی ہے — اور ہم نے تمہارے لیے واضح نور نازل کیا",
"""۱۔ نبی ﷺ — قرآن کے ساتھ واضح دلیل اور نور۔
۲۔ ’’يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُم بُرْهَانٌ مِّن رَّبِّكُمْ‘‘ — اے لوگو! تمہارے پاس تمہارے رب کی طرف سے ایک واضح دلیل آ چکی ہے — یعنی نبی ﷺ اور قرآن — اللہ کی واضح دلیل۔
۳۔ ’’وَأَنزَلْنَا إِلَيْكُمْ نُورًا مُّبِينًا‘‘ — اور ہم نے تمہارے لیے واضح نور نازل کیا — یعنی قرآن — جو واضح نور ہے۔
۴۔ عملی سبق: قرآن کو اپنا نور بناؤ؛ یہ واضح دلیل ہے — شک مت کرو۔"""
),
668: (
"پس جو لوگ اللہ پر ایمان لائے اور اس سے مضبوط رشتہ جوڑے — وہ انہیں اپنی رحمت اور فضل میں داخل کرے گا — اور انہیں اس کی طرف سیدھے راستے کی ہدایت دے گا",
"""۱۔ ایمان اور اللہ سے وابستگی — رحمت اور ہدایت کی کنجی۔
۲۔ ’’فَأَمَّا الَّذِينَ آمَنُوا بِاللّٰہِ وَاعْتَصَمُوا بِهِ فَسَيُدْخِلُهُمْ فِي رَحْمَۃٍ مِّنْهُ وَفَضْلٍ‘‘ — پس جو لوگ اللہ پر ایمان لائے اور اس سے مضبوط رشتہ جوڑے — وہ انہیں اپنی رحمت اور فضل میں داخل کرے گا۔
۳۔ ’’وَيَهْدِيهِمْ إِلَيْهِ صِرَاطًا مُّسْتَقِيمًا‘‘ — اور انہیں اس کی طرف سیدھے راستے کی ہدایت دے گا۔
۴۔ عملی سبق: اللہ سے مضبوط رشتہ رکھو؛ اللہ تمہیں اپنی رحمت اور سیدھے راستے کی ہدایت دے گا۔"""
),
669: (
"وہ آپ سے فتویٰ مانگتے ہیں — آپ کہیں: اللہ تمہیں کلالہ (میراث) کے بارے میں فتویٰ دیتا ہے — اگر کوئی شخص مر جائے جس کی کوئی اولاد نہ ہو اور اس کی ایک بہن ہو تو اس کے لیے اس کی چھوڑی ہوئی میراث کا آدھا ہے — اور وہ اس کی وارث ہوگی اگر اس کی کوئی اولاد نہ ہو — پھر اگر دو بہنیں ہوں تو انہیں چھوڑی ہوئی میراث کا دو تہائی حصہ ہے — اور اگر بھائی بہن — مرد اور عورتیں — ہوں تو مرد کے لیے دو عورتوں کے برابر حصہ ہے — اللہ تمہیں واضح کرتا ہے (تاکہ) تم گمراہ نہ ہو — اور اللہ ہر چیز کو جانتا ہے",
"""۱۔ کلالہ (ایسا شخص جس کی اولاد اور والدین نہ ہوں) کی میراث — اللہ کا مقررہ نظام۔
۲۔ ’’يَسْتَفْتُونَكَ قُلِ اللّٰہُ يُفْتِيكُمْ فِي الْكَلَالَۃِ‘‘ — وہ آپ سے فتویٰ مانگتے ہیں — آپ کہیں: اللہ تمہیں کلالہ (میراث) کے بارے میں فتویٰ دیتا ہے — یعنی یہ حکم اللہ کی طرف سے ہے۔
۳۔ ’’إِنِ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ‘‘ — اگر کوئی شخص مر جائے جس کی کوئی اولاد نہ ہو اور اس کی ایک بہن ہو تو اس کے لیے اس کی چھوڑی ہوئی میراث کا آدھا ہے۔
۴۔ ’’وَهُوَ يَرِثُهَا إِن لَّمْ يَكُن لَّهَا وَلَدٌ‘‘ — اور وہ اس کی وارث ہوگی اگر اس کی کوئی اولاد نہ ہو — یعنی بہن کی وفات پر بھائی وارث ہوتا ہے۔
۵۔ ’’فَإِن كَانَتَا اثْنَتَيْنِ فَلَهُمَا الثُّلُثَانِ مِمَّا تَرَكَ‘‘ — پھر اگر دو بہنیں ہوں تو انہیں چھوڑی ہوئی میراث کا دو تہائی حصہ ہے۔
۶۔ ’’وَإِن كَانُوا إِخْوَۃً رِّجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ‘‘ — اور اگر بھائی بہن — مرد اور عورتیں — ہوں تو مرد کے لیے دو عورتوں کے برابر حصہ ہے۔
۷۔ ’’يُبَيِّنُ اللّٰہُ لَكُمْ أَن تَضِلُّوا وَاللّٰہُ بِكُلِّ شَيْءٍ عَلِيمٌ‘‘ — اللہ تمہیں واضح کرتا ہے (تاکہ) تم گمراہ نہ ہو — اور اللہ ہر چیز کو جانتا ہے۔
۸۔ عملی سبق: کلالہ کی میراث اللہ کے مقرر کردہ حصوں کے مطابق تقسیم کرو؛ اپنی مرضی سے تبدیلی نہ کرو۔"""
),
}
